import manifest from "@/content/study/manifest.json";

/** One imported study guide (generated by `npm run study:import`). */
export interface StudyDoc {
  slug: string;
  title: string;
  description: string;
  source: string;
  bytes: number;
  updatedAt: string;
  emoji: string;
  /** Tailwind classes for the emoji tile. */
  accent: string;
}

export type HighlightColor = "yellow" | "green" | "pink" | "blue";
export const HIGHLIGHT_COLORS: HighlightColor[] = ["yellow", "green", "pink", "blue"];

/** Swatch colours shown in the toolbar (the in-document colours live in the injected CSS). */
export const HIGHLIGHT_SWATCH: Record<HighlightColor, string> = {
  yellow: "#ffd54f",
  green: "#6ee7b7",
  pink: "#f9a8d4",
  blue: "#93c5fd",
};

export interface StudyAnnotation {
  id: string;
  user_id?: string;
  doc: string;
  kind: "highlight" | "note";
  color: HighlightColor | null;
  quote: string | null;
  prefix: string | null;
  suffix: string | null;
  start_offset: number | null;
  note: string | null;
  created_at: string;
  updated_at: string;
}

export type StudyCounts = Record<string, { highlights: number; notes: number }>;

/** Look & feel per guide. Unknown (newly imported) guides fall back to a default. */
const STYLE: Record<string, { emoji: string; accent: string }> = {
  "ai-fundamentals-notes": { emoji: "🧠", accent: "bg-violet-soft text-violet" },
  "claude-field-guide": { emoji: "✳️", accent: "bg-coral-soft text-coral-deep" },
  "docker-field-guide": { emoji: "🐳", accent: "bg-indigo-soft text-indigo" },
  "fastapi-field-guide": { emoji: "⚡", accent: "bg-mint-soft text-mint" },
  "langchain-v1-field-guide": { emoji: "🦜", accent: "bg-amber-soft text-amber" },
  "mcp-field-guide": { emoji: "🔌", accent: "bg-violet-soft text-violet" },
  "pydantic-field-guide": { emoji: "🧩", accent: "bg-coral-soft text-coral-deep" },
  "rag-field-guide": { emoji: "🔎", accent: "bg-amber-soft text-amber" },
  "vector-search-rag-notes": { emoji: "🧭", accent: "bg-mint-soft text-mint" },
};

const DEFAULT_STYLE = { emoji: "📘", accent: "bg-bg-tint text-ink-soft" };

export const STUDY_DOCS: StudyDoc[] = manifest
  .map((m) => ({ ...m, ...DEFAULT_STYLE, ...STYLE[m.slug] }))
  .sort((a, b) => a.title.localeCompare(b.title));

export function getStudyDoc(slug: string): StudyDoc | undefined {
  return STUDY_DOCS.find((d) => d.slug === slug);
}
